/* The Interactive Classroom: Grade 3 Social Studies — People and Environments: living and working in Ontario */
(function(){
"use strict";
const P=window.PM;if(!P||!P.unit)return;const U=P.unit,R=P.R,S=P.S;

/* 14 ─ Ontario on the map */
U({id:'r14',title:'Ontario on the map',strand:'Living in Ontario',codes:['B3.1','B3.2','B3.7'],
 guide:{goal:'Locate Ontario in Canada, read a political map with a title, legend, compass rose and scale, and understand that Ontario is divided into municipalities with local governments.',words:'province, capital, political map, legend, compass rose, scale, municipality',ask:['What is the capital of Ontario? Of Canada?','What does a legend show?','What is a municipality?'],home:'Find your town on a map of Ontario. Which direction is Toronto from you?'},
 watch:['Read the map!','A political map shows borders, capitals and cities. Stars mark capitals, dots mark cities.'],
 fig:'A map of Ontario with a legend and compass rose.',
 page:{story:{title:'The Road Trip Map',text:'Zara’s family planned a *road trip* across Ontario. She unfolded a big *political map*. "The *title* says *Ontario*. The *legend* shows a ★ for capitals and a • for cities." She found *Toronto* with a star in a circle: Ontario’s *capital*. Far east was *Ottawa*, the capital of all of Canada. The *compass rose* showed north was up. The *scale* said 1 cm on the map means *50 km* on the road. "Ottawa is 9 cm away," Zara measured. "That’s *450 km*!"',pics:['map','car','compass','girl'],
   acts:[[null,'home',['map','girl','compass'],'Where do we go first?'],['Toronto','city',['cn tower','car'],'Ontario’s capital!'],['Ottawa','city',['parliament','flag'],'Canada’s capital!']]},
  boxes:[{title:'Parts of a map',ex:[['map','*title*: what the map shows'],['star','*legend*: what symbols mean'],['compass','*compass rose*: N, E, S, W'],['ruler','*scale*: map distance → real distance']],cols:2},
   {title:'Ontario',text:'Ontario is a *province* of Canada. Its capital is *Toronto*. Canada’s capital, *Ottawa*, is also in Ontario. Ontario is divided into *municipalities*: cities, towns, townships and counties, each with a local government.'}],
  cards:[{q:'Capital of Ontario?',a:'*Toronto*'},{q:'Capital of Canada?',a:'*Ottawa*'}],
  words:[['legend','a box that explains the symbols on a map'],['municipality','a city, town or township with its own local government']]},
 steps:[
  {say:'Read the story',speech:'Zara’s political map had a title, a legend and a compass rose. Toronto is Ontario’s capital, and Ottawa is Canada’s capital. The scale showed that one centimetre means fifty kilometres.',set:S.row(['map','car','compass','girl'])},
  {say:'Two capitals',speech:'Toronto is the capital of Ontario, where the provincial government meets. Ottawa is the capital of Canada, where Parliament meets.',set:S.row(['cn tower','parliament'],{labels:['Toronto','Ottawa']}),
   cues:[['Toronto','cn tower','Ontario’s capital'],['Ottawa','parliament','Canada’s capital']]},
  {say:'Read a map grid',speech:'Maps often have a grid. To find a place, read the letter for the row and the number for the column. The school is in square A3.',set:{grid:{rows:3,cols:4,items:{A1:'tree',A3:'school',B2:'house',C4:'hospital',C1:'lake'}},cell:'A3'},
   cues:[['A3','A3','school']]},
  {say:'Compass and scale',speech:'The compass rose shows north, east, south and west. The scale helps us find real distances. One centimetre might mean fifty kilometres.',set:S.row(['compass','ruler','car'],{labels:['directions','scale','distance']}),
   cues:[['compass rose','compass','N E S W'],['The scale','ruler','1 cm = 50 km'],['real distances','car','how far?']]}],
 more:{title:'Did you know?',text:'Ontario is *huge*: it is bigger than France and Spain put together! More than *15 million* people live here, more than in any other province.',pics:['map','flag']},
 rounds:[R.q('What is the capital of *Ontario*?',['Toronto','Ottawa','Montreal'],'Toronto'),R.q('What is the capital of *Canada*?',['Ottawa','Toronto','Vancouver'],'Ottawa'),
  R.q('What does a *legend* show?',['what the symbols mean','the weather','a story'],'what the symbols mean'),R.grid('Tap the square with the *hospital*.',{rows:3,cols:4,items:{A1:'tree',A3:'school',B2:'house',C4:'hospital',C1:'lake'}},'C4'),
  R.q('What does the compass rose show?',['directions','temperature','time'],'directions'),R.q('If 1 cm = 50 km, how far is 2 cm?',['100 km','50 km','2 km'],'100 km'),
  R.tf('Ontario is divided into municipalities with local governments.',true),R.q('On Zara’s map, what showed a capital?',['a star','a dot','a triangle'],'a star')],
 tries:[['Draw a map of your bedroom with a legend.','use symbols for bed, desk, door'],['Which direction is the sunrise?','*east*']]});

/* 15 ─ Landform regions */
U({id:'r15',title:'Ontario’s landform regions',strand:'Living in Ontario',codes:['B3.3','B1.1'],
 guide:{goal:'Identify and describe Ontario’s major landform regions: the Canadian Shield, the Great Lakes–St. Lawrence Lowlands and the Hudson Bay Lowlands.',words:'landform, region, Canadian Shield, lowlands, bedrock, wetland, fertile',ask:['Which region covers most of Ontario?','Why do most people live in the Lowlands?','What is the Hudson Bay Lowlands like?'],home:'On a map of Ontario, colour the three landform regions.'},
 watch:['Three big regions!','Rocky Shield with lakes and forests in the middle, flat farmland in the south, and swampy lowlands in the far north.'],
 fig:'Ontario’s three landform regions.',
 page:{story:{title:'Flight Over Ontario',text:'Pilot Sam flew Leah in a small *float plane* from south to north. Below them, *flat green farms* and busy cities spread out. "The *Great Lakes–St. Lawrence Lowlands*," said Sam. "Rich soil and mild weather. Most people live here!" Then the land became *rocky*, with *thousands of lakes* and dark pine forests. "The *Canadian Shield*: old, hard rock full of minerals." Far north, the land turned *flat and soggy*, with polar bears near the shore. "The *Hudson Bay Lowlands*: wetlands as far as you can see!"',pics:['airplane','corn','pine','polar bear'],
   acts:[[null,'farm',['airplane','tractor'],'Flat green farms!'],['Canadian Shield','shield',['airplane','moose'],'Rocks and lakes!'],['Hudson Bay Lowlands','arctic',['polar bear','airplane'],'Polar bears!']]},
  boxes:[{title:'Three landform regions',ex:[['corn','*Great Lakes–St. Lawrence Lowlands*: flat, fertile, warm, most people'],['pine','*Canadian Shield*: rock, lakes, forests, minerals'],['polar bear','*Hudson Bay Lowlands*: flat, wet, cold, few people']],cols:1}],
  cards:[{q:'Which region covers most of Ontario?',pics:['pine'],a:'the *Canadian Shield*'},{q:'Where do most Ontarians live?',a:'the *Great Lakes–St. Lawrence Lowlands*'}],
  words:[['landform','a natural shape of the land, like a hill or plain'],['region','an area with features that make it different']]},
 steps:[
  {say:'Read the story',speech:'In the south, the Great Lakes–St. Lawrence Lowlands had flat farms and cities. In the middle, the Canadian Shield had rock, lakes and forests. In the far north, the Hudson Bay Lowlands were flat and soggy, with polar bears.',set:S.row(['airplane','corn','pine','polar bear'])},
  {say:'The southern lowlands',speech:'The Great Lakes–St. Lawrence Lowlands are flat with rich soil and warmer weather. It is great for farming, and most Ontarians live here.',set:S.row(['corn','tractor','city'],{labels:['farms','rich soil','cities']}),
   cues:[['rich soil','corn','fertile'],['farming','tractor','farms'],['most Ontarians','city','cities']]},
  {say:'The Canadian Shield',speech:'The Canadian Shield is ancient rock covered by thin soil, forests and thousands of lakes. It has minerals like gold, nickel and copper.',set:S.row(['rock','pine','lake','ore'],{labels:['rock','forests','lakes','minerals']}),
   cues:[['ancient rock','rock','old rock'],['forests','pine','forests'],['thousands of lakes','lake','lakes'],['minerals','ore','gold, nickel']]},
  {say:'The northern lowlands',speech:'The Hudson Bay Lowlands are flat and wet, with swamps and bogs called muskeg. It is cold, and few people live there, but caribou, geese and polar bears do.',set:S.row(['caribou','goose','polar bear'],{labels:['caribou','geese','polar bears']}),
   cues:[['caribou','caribou','caribou'],['geese','goose','geese'],['polar bears','polar bear','Hudson Bay']]}],
 more:{title:'Did you know?',text:'The rocks of the *Canadian Shield* are some of the *oldest on Earth*, more than *two billion* years old. That is older than the dinosaurs by a lot!',pics:['rock','dinosaur']},
 rounds:[R.q('Which region has flat, rich farmland?',['Great Lakes–St. Lawrence Lowlands','Canadian Shield','Hudson Bay Lowlands'],'Great Lakes–St. Lawrence Lowlands'),R.q('Which region has rock, lakes and forests?',['Canadian Shield','Hudson Bay Lowlands','Great Lakes–St. Lawrence Lowlands'],'Canadian Shield'),
  R.q('Where did Leah see polar bears?',['Hudson Bay Lowlands','Toronto','the farms'],'Hudson Bay Lowlands'),R.q('Where do most people in Ontario live?',['in the southern lowlands','in the far north','on the Shield'],'in the southern lowlands'),
  R.q('What is *muskeg*?',['swampy, boggy land','a mountain','a city'],'swampy, boggy land'),R.q('Which minerals are in the Canadian Shield?',['gold and nickel','chocolate','salt water'],'gold and nickel'),
  R.tf('The Canadian Shield covers most of Ontario.',true),R.q('What kind of plane did Pilot Sam fly?',['a float plane','a jet','a helicopter'],'a float plane')],
 tries:[['Which landform region do you live in?','most likely the *Lowlands*!'],['Why is the Shield good for cottages?','*lakes*, rocks and forests']]});

/* 16 ─ Lakes and rivers */
U({id:'r16',title:'Lakes and rivers of Ontario',strand:'Living in Ontario',codes:['B1.1','B3.3'],
 guide:{goal:'Name the Great Lakes and important rivers of Ontario, and explain how water shapes where people live, work and play.',words:'Great Lakes, Superior, Michigan, Huron, Erie, Ontario, river, shipping, freshwater',ask:['Name the five Great Lakes.','How do people use lakes and rivers?','Why are cities often near water?'],home:'Use HOMES to remember the Great Lakes: Huron, Ontario, Michigan, Erie, Superior.'},
 watch:['HOMES!','Huron, Ontario, Michigan, Erie and Superior: the five Great Lakes hold a fifth of the world’s fresh water.'],
 fig:'The Great Lakes with ships and lighthouses.',
 page:{story:{title:'The Freighter’s Journey',text:'Captain Ruiz steered a long *freighter* loaded with wheat. She started in *Lake Superior*, the biggest and coldest Great Lake. She sailed through locks into *Lake Huron*, then down to *Lake Erie*. At *Niagara*, the ship climbed down a giant staircase of *locks* in the Welland Canal, around the famous *falls*. Then across *Lake Ontario* and down the *St. Lawrence River* to the ocean! "The Great Lakes are a *water highway*," she told her crew.',pics:['ship','lake','lighthouse','woman'],
   acts:[[null,'lake',['ship','lighthouse'],'Lake Superior!'],['locks','river',['ship','bridge'],'Down the water staircase!'],['St. Lawrence River','ocean',['ship','seagull'],'To the ocean!']]},
  boxes:[{title:'The Great Lakes',text:'Remember *HOMES*:',lines:['*H*uron','*O*ntario','*M*ichigan (in the USA)','*E*rie','*S*uperior: the biggest']},
   {title:'Using our waters',ex:[['ship','*shipping* goods'],['droplet','*drinking* water'],['fish','*fishing*'],['canoe','*fun*: swimming, boating'],['light bulb','*power* from dams and Niagara Falls']],cols:3}],
  cards:[{q:'Which Great Lake is the biggest?',a:'*Lake Superior*'},{q:'Which river joins the Great Lakes to the ocean?',a:'the *St. Lawrence River*'}],
  words:[['freshwater','water that is not salty, like in lakes and rivers'],['lock','a part of a canal that raises or lowers ships']]},
 steps:[
  {say:'Read the story',speech:'Captain Ruiz sailed a freighter from Lake Superior through Lake Huron and Lake Erie, down the locks around Niagara Falls, across Lake Ontario and down the St. Lawrence River to the ocean. A water highway!',set:S.row(['ship','lake','lighthouse','woman'])},
  {say:'HOMES',speech:'The five Great Lakes are Huron, Ontario, Michigan, Erie and Superior. Together they hold about one fifth of all the fresh lake water in the world.',set:S.row(['lake','lighthouse','fish'],{labels:['5 Great Lakes','shores','fresh water']}),
   cues:[['Huron, Ontario, Michigan, Erie and Superior','lake','HOMES'],['fresh lake water','fish','freshwater']]},
  {say:'A water highway',speech:'Big ships carry wheat, iron and cars across the lakes and through canals and locks to the Atlantic Ocean.',set:S.row(['ship','truck','ocean'],{labels:['freighters','goods','to the ocean']}),
   cues:[['Big ships','ship','shipping'],['wheat, iron and cars','truck','goods'],['Atlantic Ocean','ocean','ocean']]},
  {say:'Water for life',speech:'Lakes and rivers give us drinking water, fish, power from waterfalls and dams, and places to swim and paddle.',set:S.row(['droplet','salmon','light bulb','canoe'],{labels:['drinking','fishing','power','fun']}),
   cues:[['drinking water','droplet','drink'],['fish','salmon','fishing'],['power','light bulb','hydro power'],['paddle','canoe','recreation']]}],
 more:{title:'Did you know?',text:'*Niagara Falls* is so powerful that it makes electricity for millions of homes. About *2800 cubic metres* of water go over the falls every second, enough to fill an Olympic swimming pool!',pics:['droplet','light bulb']},
 rounds:[R.q('Which is the biggest Great Lake?',['Lake Superior','Lake Erie','Lake Ontario'],'Lake Superior'),R.q('What does HOMES help you remember?',['the five Great Lakes','five cities','five rivers'],'the five Great Lakes'),
  R.q('Which river leads to the ocean?',['the St. Lawrence River','the Thames','the Don'],'the St. Lawrence River'),R.q('What did the freighter carry?',['wheat','people only','snow'],'wheat'),
  R.q('How do ships get around Niagara Falls?',['through locks in a canal','they jump','they fly'],'through locks in a canal'),R.pick('Tap the ways people use lakes.',['ship','droplet','canoe','tv'],['ship','droplet','canoe']),
  R.tf('Lake water in the Great Lakes is fresh, not salty.',true),R.q('Which Great Lake is NOT in Ontario?',['Lake Michigan','Lake Huron','Lake Erie'],'Lake Michigan')],
 tries:[['Trace the freighter’s trip on a map.','Superior → Huron → Erie → Ontario → St. Lawrence'],['Where does your tap water come from?','often a *lake* or river!']]});

/* 17 ─ Local government */
U({id:'r17',title:'Local government and services',strand:'Living in Ontario',codes:['B3.1','B3.2'],
 guide:{goal:'Describe how municipal governments (councils and mayors) provide services such as water, garbage pickup, libraries, parks, roads and fire protection, and make rules about building and land use.',words:'municipal, council, mayor, service, taxes, by-law',ask:['Who leads a city council?','Name three services your town provides.','How do towns pay for services?'],home:'Find out who your mayor is. What services does your town give your family?'},
 watch:['Services for everyone!','The town council decides where parks go, picks up garbage, and keeps tap water clean.'],
 fig:'Town services: water, garbage trucks, libraries and parks.',
 page:{story:{title:'A Day With the Mayor',text:'Rosa won a contest to spend a day with *Mayor Kim*. First they visited the *water treatment plant*, where clean water is made for every tap in town. Next they waved at a *garbage truck* and a *snowplow*. At the *library*, kids were reading. At *council*, the councillors voted to build a new *park*. "How do we pay for all this?" asked Rosa. "Families and businesses pay *taxes*," said the mayor. "Then we share *services* with everyone."',pics:['library','truck','park','woman'],
   acts:[[null,'city',['woman','girl','truck'],'Our town works for us!'],['library','city',['library','book'],'A library for everyone!'],['new park','park',['swing','tree','girl'],'A new park!']]},
  boxes:[{title:'Municipal services',ex:[['droplet','clean *water*'],['garbage','*garbage* and recycling'],['library','*libraries*'],['park','*parks* and rinks'],['fire truck','*fire* department'],['bus','*buses* and roads']],cols:3},
   {title:'Who decides?',text:'Each municipality has a *council* led by a *mayor* (or reeve). People *vote* for them. The council makes local rules called *by-laws*, like where houses and stores can be built.'}],
  cards:[{q:'Who leads a town council?',a:'the *mayor*'},{q:'How are services paid for?',a:'with *taxes*'}],
  words:[['council','a group of people elected to make decisions for a town or city'],['service','work done to help people, like garbage pickup']]},
 steps:[
  {say:'Read the story',speech:'Rosa visited the water treatment plant, saw a garbage truck and a snowplow, and visited the library. The council voted for a new park. Taxes pay for services everyone shares.',set:S.row(['library','truck','park','woman'])},
  {say:'Services we share',speech:'Towns give us clean tap water, garbage and recycling pickup, libraries, parks, buses and firefighters.',set:S.row(['droplet','garbage','library','fire truck'],{labels:['water','garbage','library','fire']}),
   cues:[['clean tap water','droplet','water'],['garbage and recycling','garbage','pickup'],['libraries','library','books'],['firefighters','fire truck','safety']]},
  {say:'The council',speech:'People vote to elect a mayor and councillors. They meet at city hall to make decisions and by-laws for the community.',set:S.row(['woman','man','parliament'],{labels:['mayor','councillor','city hall']}),
   cues:[['a mayor','woman','mayor'],['councillors','man','council'],['city hall','parliament','meetings']]},
  {say:'Taxes',speech:'Families and businesses pay taxes to the town. The town uses that money to pay for roads, snowplows, parks and libraries.',set:S.row(['coin','road','park'],{labels:['taxes','roads','parks']}),
   cues:[['pay taxes','coin','taxes'],['roads','road','roads'],['parks','park','parks']]}],
 more:{title:'Did you know?',text:'Some young people in Ontario join *youth councils*, where they share ideas with the mayor about parks, sports and the environment. Your ideas matter!',pics:['girl','boy']},
 rounds:[R.q('Who leads a town council?',['the mayor','the queen','a teacher'],'the mayor'),R.q('How do towns pay for services?',['taxes','selling toys','luck'],'taxes'),
  R.pick('Tap town services.',['library','fire truck','garbage','castle'],['library','fire truck','garbage']),R.q('What did the council vote to build?',['a new park','a castle','a zoo'],'a new park'),
  R.q('Where is clean tap water made?',['the water treatment plant','the library','the park'],'the water treatment plant'),R.q('What is a *by-law*?',['a local rule made by a town','a book','a kind of tax'],'a local rule made by a town'),
  R.tf('People vote to elect their mayor.',true),R.q('Who spent a day with the mayor?',['Rosa','Zara','Leah'],'Rosa')],
 tries:[['Write a letter to your mayor about an idea for your town.','e.g. more bike lanes, a new rink'],['Which service did you use today?','water, roads, school bus…']]});

/* 18 ─ How we use land */
U({id:'r18',title:'How we use land',strand:'Living in Ontario',codes:['B3.5','B3.6','B3.7'],
 guide:{goal:'Identify major types of land use (residential, commercial, industrial, agricultural, recreational, transportation, protected) and how they meet people’s needs and wants; compare land use in two municipalities.',words:'land use, residential, commercial, industrial, agricultural, recreational, protected',ask:['What is residential land used for?','Where are factories built?','Why do we protect some land?'],home:'On a walk, spot each kind of land use: homes, stores, factories, parks, farms, roads.'},
 watch:['Every piece of land has a job!','Homes are residential, stores are commercial, factories are industrial, farms are agricultural.'],
 fig:'A land-use map with colours for each use.',
 page:{story:{title:'Design Your Own Town',text:'Mr. Ali gave the class a giant *blank map*. "Design a town," he said, "but every piece of land needs a *use*." The class coloured *yellow* for houses: *residential*. *Red* for stores: *commercial*. *Purple* for the factory: *industrial*, far from homes because of the noise. *Green* for farms: *agricultural*, and *light green* for parks: *recreational*. Grey for *roads*. Devon added a dark green forest. "We’ll *protect* it for the animals," he said. Their town was perfect.',pics:['map','house','store','factory'],
   acts:[[null,'classroom',['map','teacher','boy'],'Design a town!'],['residential','town',['house','store'],'Homes and stores!'],['factory','city',['factory','truck'],'Far from the homes!'],['protect','forest',['tree','deer'],'For the animals!']]},
  boxes:[{title:'Kinds of land use',ex:[['house','*residential*: homes'],['store','*commercial*: stores, offices'],['factory','*industrial*: factories'],['tractor','*agricultural*: farms'],['park','*recreational*: parks, rinks'],['road','*transportation*: roads, railways'],['tree','*protected*: nature areas']],cols:2}],
  cards:[{q:'A grocery store is which land use?',pics:['store'],a:'*commercial*'},{q:'Farms are which land use?',pics:['tractor'],a:'*agricultural*'}],
  words:[['land use','how people use a piece of land'],['protected area','land kept natural for plants and animals']]},
 steps:[
  {say:'Read the story',speech:'The class coloured houses yellow for residential, stores red for commercial, the factory purple for industrial, farms green for agricultural, parks for recreational, grey roads, and a protected forest.',set:S.row(['map','house','store','factory'])},
  {say:'Homes and stores',speech:'Residential land has houses and apartments. Commercial land has stores, restaurants and offices where people buy and sell.',set:S.row(['house','skyscraper','store'],{labels:['residential','offices','commercial']}),
   cues:[['Residential','house','homes'],['offices','skyscraper','commercial'],['stores','store','commercial']]},
  {say:'Factories and farms',speech:'Industrial land has factories that make things. It is usually away from homes. Agricultural land has farms that grow our food.',set:S.row(['factory','tractor','barn'],{labels:['industrial','agricultural','farm']}),
   cues:[['Industrial','factory','factories'],['Agricultural','tractor','farms'],['grow our food','barn','food']]},
  {say:'Play, travel and nature',speech:'Recreational land is for fun: parks, rinks and trails. Transportation land has roads and railways. Protected land keeps nature safe.',set:S.row(['park','train','moose'],{labels:['recreational','transportation','protected']}),
   cues:[['Recreational','park','fun'],['railways','train','travel'],['Protected','moose','nature']]}],
 more:{title:'Did you know?',text:'Ontario’s *Greenbelt* protects about *800 000 hectares* of farmland, forests and wetlands around Toronto and the Golden Horseshoe, so cities don’t spread over all of it.',pics:['tree','tractor']},
 rounds:[R.sort('Sort: *residential* or *commercial*?',['residential','commercial'],[['house',0],['store',1],['house2',0],['shopping cart',1]]),R.q('A factory is which land use?',['industrial','residential','recreational'],'industrial'),
  R.q('Why was the factory far from homes?',['because of the noise','to be close to school','it was a park'],'because of the noise'),R.q('What colour did the class use for farms?',['green','red','purple'],'green'),
  R.q('Which land use is a hockey rink?',['recreational','industrial','agricultural'],'recreational'),R.q('Why did Devon protect the forest?',['for the animals','to build a mall','to make a road'],'for the animals'),
  R.tf('Roads and railways are transportation land use.',true),R.q('Agricultural land is used for…',['farming','factories','houses'],'farming')],
 tries:[['Draw a land-use map of your street with colours.','make a *legend*!'],['Which land use is most common near your home?','often *residential*']]});

/* 19 ─ Farming communities */
U({id:'r19',title:'Farming communities',strand:'Living in Ontario',codes:['B1.1','B1.2','B3.4'],
 guide:{goal:'Describe how rich soil and a mild climate in southern Ontario support farming, the jobs in farming communities, and the foods Ontario grows.',words:'agriculture, crops, livestock, orchard, greenhouse, harvest, climate',ask:['Why is southern Ontario good for farming?','What jobs are on a farm?','What foods does Ontario grow?'],home:'At the grocery store, look for “Product of Ontario” stickers. What did you find?'},
 watch:['Food from Ontario!','Rich soil and warm summers grow corn, apples, peaches, vegetables and more.'],
 fig:'Ontario farms with crops, orchards and animals.',
 page:{story:{title:'Summer on the Farm',text:'Every summer, Jacob stays with his aunt and uncle on their farm near *Niagara*. The soil is *rich* and the lake keeps the weather *mild*. In the *orchard*, he picks *peaches* and *cherries*. In the barn, he helps feed the *dairy cows*. Workers drive *tractors* and run the *greenhouse*, where tomatoes grow even in winter. On Saturday, they sell fruit at the *farmers’ market* in town. "Farming is lots of jobs at once," Uncle Dev says. "And it feeds all of Ontario!"',pics:['peach','cow','tractor','boy'],
   acts:[[null,'orchard',['peach','basket','boy'],'Peaches!'],['dairy cows','farm',['cow','barn','boy'],'Milking time!'],['farmers’ market','town',['store','apple','man'],'Fresh from the farm!']]},
  boxes:[{title:'Why farm here?',text:'Southern Ontario has *rich soil*, *flat land*, *warm summers* and lots of *water*. That makes it one of the best farming regions in Canada.'},
   {title:'What Ontario farms grow',ex:[['corn','*corn* and soybeans'],['apple','*apples*, peaches, cherries'],['tomato','*vegetables* (and greenhouses)'],['cow','*dairy* (milk, cheese)'],['chicken','*eggs* and chicken'],['maple leaf','*maple syrup*']],cols:3}],
  cards:[{q:'Why is Niagara good for fruit?',a:'*rich soil* and *mild* weather'},{q:'Name a farm job.',a:'*farmer*, truck driver, market seller, vet…'}],
  words:[['agriculture','farming: growing crops and raising animals'],['greenhouse','a glass building where plants grow in warm air']]},
 steps:[
  {say:'Read the story',speech:'Near Niagara, the soil is rich and the weather mild. Jacob picks peaches and cherries, feeds dairy cows, and sees tomatoes in the greenhouse. On Saturday, they sell fruit at the farmers’ market.',set:S.row(['peach','cow','tractor','boy'])},
  {say:'Crops',speech:'Ontario farmers grow corn, soybeans and wheat in big fields, and apples, peaches and grapes in orchards and vineyards.',set:S.row(['corn','apple','peach','grapes'],{labels:['corn','apples','peaches','grapes']}),
   cues:[['corn','corn','fields'],['apples','apple','orchards'],['peaches','peach','Niagara'],['grapes','grapes','vineyards']]},
  {say:'Animals',speech:'Livestock farms raise dairy cows for milk and cheese, chickens for eggs, and pigs and cattle for meat.',set:S.row(['cow','chicken','pig'],{labels:['dairy','eggs','pigs']}),
   cues:[['dairy cows','cow','milk'],['chickens','chicken','eggs'],['pigs','pig','farm']]},
  {say:'Farm jobs',speech:'Farming communities have many jobs: farmers, truck drivers, mechanics who fix tractors, vets for animals, and sellers at markets.',set:S.row(['farmer','truck','tractor','store'],{labels:['farmer','driver','mechanic','seller']}),
   cues:[['farmers','farmer','grow'],['truck drivers','truck','deliver'],['mechanics','tractor','fix'],['sellers','store','sell']]}],
 more:{title:'Did you know?',text:'Ontario has about *48 000* farms! Ontario farmers grow most of the *apples* and *grapes* in Canada, and the Holland Marsh is called *Canada’s Salad Bowl*.',pics:['apple','lettuce']},
 rounds:[R.q('Why is southern Ontario good for farming?',['rich soil and mild weather','lots of rock','very cold'],'rich soil and mild weather'),R.q('What did Jacob pick in the orchard?',['peaches and cherries','potatoes','corn'],'peaches and cherries'),
  R.q('Where do tomatoes grow in winter?',['in a greenhouse','outside in the snow','in the lake'],'in a greenhouse'),R.sort('Sort: *crop* or *animal*?',['crop','animal'],[['corn',0],['cow',1],['apple',0],['chicken',1]]),
  R.q('Where did they sell fruit?',['the farmers’ market','the library','the hospital'],'the farmers’ market'),R.q('Dairy cows give us…',['milk','eggs','wool'],'milk'),
  R.tf('Farming communities have many different jobs.',true),R.q('What is *agriculture*?',['farming','mining','fishing'],'farming')],
 tries:[['Make a menu using only Ontario foods.','e.g. corn, apples, cheese, maple syrup'],['Visit a pick-your-own farm in summer!','strawberries in June, apples in fall']]});

/* 20 ─ Mining and forestry */
U({id:'r20',title:'Mining and forestry towns',strand:'Living in Ontario',codes:['B1.2','B3.4','B2.1'],
 guide:{goal:'Describe how natural resources in northern Ontario (minerals, forests) create communities and jobs in mining and forestry, and the effects on the environment.',words:'natural resource, mining, mineral, forestry, logging, mill, replant',ask:['What is a natural resource?','What jobs are in a mining town?','Why do forestry companies replant trees?'],home:'Find something at home made from wood and something made from metal.'},
 watch:['Treasures from the land!','Miners dig nickel and gold from the Shield. Forestry workers cut trees for wood and paper, then replant.'],
 fig:'A mine and a forest with logging trucks.',
 page:{story:{title:'Two Northern Towns',text:'Maya lives in *Sudbury*, a city built on *mining*. Her mom is an engineer at a *nickel mine* deep underground. Nickel goes into coins, batteries and cars! Maya’s pen pal, Liam, lives in a *forestry* town near *Thunder Bay*. His dad drives a *logging truck*, and his aunt works at the *paper mill*. "After cutting, crews *replant* thousands of seedlings," Liam wrote. "Our forests grow back." Both towns *grew* because of the *natural resources* nearby.',pics:['pickaxe','ore','logging truck','pine'],
   acts:[[null,'mine',['mine cart','woman','pickaxe'],'Deep underground!'],['logging truck','forest',['logging truck','pine'],'Logs for the mill!'],['replant','forest',['seedling','boy'],'The forest grows back!']]},
  boxes:[{title:'Natural resources',text:'A *natural resource* is something from nature that people use: *minerals*, *trees*, *water*, *soil* and *fish*.',ex:[['ore','*minerals*: nickel, gold, copper'],['pine','*trees*: lumber and paper'],['droplet','*water*: power and drinking']],cols:3},
   {title:'Jobs and the environment',text:'Resource towns have jobs for miners, engineers, truck drivers, mill workers and *tree planters*. Mines and logging can harm land and water, so companies must clean up and *replant*.'}],
  cards:[{q:'What is Sudbury known for?',pics:['ore'],a:'*nickel mining*'},{q:'Why replant trees?',pics:['seedling'],a:'so *forests grow back*'}],
  words:[['natural resource','something from nature that people use'],['forestry','growing, cutting and caring for forests']]},
 steps:[
  {say:'Read the story',speech:'Maya lives in Sudbury, where her mom works at a nickel mine. Liam lives near Thunder Bay, where his dad drives a logging truck and his aunt works at a paper mill. Crews replant thousands of seedlings.',set:S.row(['pickaxe','ore','logging truck','pine'])},
  {say:'Mining',speech:'Miners dig deep into the Canadian Shield for nickel, gold and copper. These minerals become coins, wires, batteries and cars.',set:S.row(['mine cart','ore','coin'],{labels:['mine','minerals','coins']}),
   cues:[['Miners dig','mine cart','mining'],['nickel, gold and copper','ore','minerals'],['coins','coin','products']]},
  {say:'Forestry',speech:'Forestry workers cut trees. Logging trucks carry logs to mills, where they become lumber for houses and paper for books.',set:S.row(['pine','logging truck','paper'],{labels:['trees','logs','paper']}),
   cues:[['cut trees','pine','forests'],['Logging trucks','logging truck','logs'],['paper','paper','products']]},
  {say:'Caring for the land',speech:'Mines can pollute water and leave bare land. Logging removes animal homes. So companies clean up, plant grass, and replant millions of trees.',set:S.row(['droplet','seedling','moose'],{labels:['clean water','replant','animal homes']}),
   cues:[['pollute water','droplet','clean up'],['replant','seedling','new trees'],['animal homes','moose','habitats']]}],
 more:{title:'Did you know?',text:'Sudbury once had bare black hills from mining pollution. People planted more than *10 million trees* to bring the land back to life, and now it is green again!',pics:['pine','seedling']},
 rounds:[R.q('What is a *natural resource*?',['something from nature that people use','a kind of store','a toy'],'something from nature that people use'),R.q('What is mined in Sudbury?',['nickel','chocolate','wood'],'nickel'),
  R.q('What does Liam’s dad drive?',['a logging truck','a bus','a boat'],'a logging truck'),R.q('What do crews do after cutting trees?',['replant seedlings','build malls','nothing'],'replant seedlings'),
  R.pick('Tap the natural resources.',['ore','pine','droplet','tv'],['ore','pine','droplet']),R.q('What is paper made from?',['trees','rocks','water only'],'trees'),
  R.tf('Mining can pollute water, so companies must clean up.',true),R.q('How many trees did Sudbury plant?',['more than 10 million','10','100'],'more than 10 million')],
 tries:[['Find 3 things made from metal and 3 from wood at home.','spoon, keys…; table, pencil…'],['Why should we recycle paper?','to save *trees*']]});

/* 21 ─ Cities and jobs */
U({id:'r21',title:'Cities and jobs',strand:'Living in Ontario',codes:['B1.2','B3.4','B3.6'],
 guide:{goal:'Describe the main types of jobs in Ontario cities (services, manufacturing, technology, government, tourism), and compare jobs in two municipal regions.',words:'manufacturing, service, tourism, technology, government, employment',ask:['What kinds of jobs are in a big city?','How are city jobs different from northern jobs?','Why do cities have so many jobs?'],home:'Ask three adults you know: what is your job? Which kind of job is it?'},
 watch:['So many jobs!','Cities have factories, hospitals, offices, theatres and tech companies. Tourists come too!'],
 fig:'A busy city with many workplaces.',
 page:{story:{title:'Career Day',text:'On *Career Day* at Lakeview School, parents came to talk about their jobs. Ahmed’s mom builds *cars* at a factory in *Oshawa*: that is *manufacturing*. Grace’s dad is a *nurse* at a Toronto hospital: a *service* job. Mr. Tremblay works for the government in *Ottawa*. Sofia’s aunt makes video games: *technology*. And Kai’s uncle is a tour guide at *Niagara Falls*: *tourism*! "Cities have so many jobs because so many *people* live and work close together," said the principal.',pics:['car','nurse','computer','skyscraper'],
   acts:[[null,'classroom',['teacher','boy','girl'],'Welcome to Career Day!'],['factory','city',['factory','car'],'Building cars!'],['Niagara Falls','river',['ship','boy'],'Tourists everywhere!']]},
  boxes:[{title:'City jobs',ex:[['car','*manufacturing*: making cars, food, steel'],['nurse','*services*: health, teaching, stores'],['computer','*technology*: software, games'],['parliament','*government*: Ottawa, Toronto'],['ship','*tourism*: Niagara Falls, CN Tower']],cols:2},
   {title:'Comparing regions',text:'In the *north*, many jobs are in *mining* and *forestry*. In the *south*, many are in *farming*, *manufacturing* and *services*. The *land* and *resources* shape the jobs.'}],
  cards:[{q:'Building cars is which kind of job?',pics:['car'],a:'*manufacturing*'},{q:'A tour guide works in…',a:'*tourism*'}],
  words:[['manufacturing','making products in factories'],['tourism','jobs that help visitors, like hotels and tour guides']]},
 steps:[
  {say:'Read the story',speech:'On Career Day, a mom builds cars in Oshawa, a dad is a nurse, Mr. Tremblay works for the government in Ottawa, an aunt makes video games, and an uncle is a tour guide at Niagara Falls.',set:S.row(['car','nurse','computer','skyscraper'])},
  {say:'Making things',speech:'Manufacturing jobs make products in factories: cars in Oshawa and Windsor, steel in Hamilton, and food in many towns.',set:S.row(['factory','car','truck'],{labels:['factory','cars','shipping']}),
   cues:[['factories','factory','manufacturing'],['cars','car','Oshawa'],['steel','truck','Hamilton']]},
  {say:'Helping people',speech:'Service jobs help people: nurses, teachers, cashiers, bus drivers and firefighters. Most city workers have service jobs.',set:S.row(['nurse','teacher','bus','fire truck'],{labels:['nurse','teacher','driver','firefighter']}),
   cues:[['nurses','nurse','health'],['teachers','teacher','education'],['bus drivers','bus','transit'],['firefighters','fire truck','safety']]},
  {say:'Ideas and visitors',speech:'Technology jobs create computer programs and games. Tourism jobs welcome visitors to places like the CN Tower and Niagara Falls.',set:S.row(['computer','cn tower','ship'],{labels:['technology','tourism','tours']}),
   cues:[['Technology','computer','tech'],['CN Tower','cn tower','tourism'],['Niagara Falls','ship','tours']]}],
 more:{title:'Did you know?',text:'*Waterloo*, Ontario, is famous for technology. Some of the first *smartphones* were designed there!',pics:['phone','computer']},
 rounds:[R.q('Building cars is which kind of job?',['manufacturing','tourism','forestry'],'manufacturing'),R.q('A nurse has which kind of job?',['service','mining','manufacturing'],'service'),
  R.q('Where does Kai’s uncle work?',['Niagara Falls','a mine','a farm'],'Niagara Falls'),R.q('Why do cities have so many jobs?',['many people live and work close together','there are no farms','it is cold'],'many people live and work close together'),
  R.sort('Sort: *north* job or *city* job?',['north','city'],[['pickaxe',0],['computer',1],['logging truck',0],['nurse',1]]),R.q('Where is Canada’s government?',['Ottawa','Sudbury','Windsor'],'Ottawa'),
  R.tf('The land and resources help shape the jobs in a region.',true),R.q('Making video games is which kind of job?',['technology','farming','fishing'],'technology')],
 tries:[['What job would you like? Which kind is it?','e.g. vet: a *service* job'],['Compare jobs in Sudbury and Toronto.','mining vs. services, tech, tourism']]});

/* 22 ─ Where people live */
U({id:'r22',title:'Where people live in Ontario',strand:'Living in Ontario',codes:['B1.3','B3.6'],
 guide:{goal:'Describe patterns in where people live in Ontario (crowded south, sparse north; cities, suburbs, rural areas) and the reasons for them, using maps.',words:'population, dense, sparse, urban, suburban, rural, pattern',ask:['Why do most people live in the south?','What does rural mean?','How is life in a city different from the country?'],home:'Is your home urban, suburban or rural? What tells you?'},
 watch:['Crowded south, quiet north!','Most Ontarians live near the Great Lakes, in big cities like Toronto. The north has few people and lots of space.'],
 fig:'A population map: many dots in the south, few in the north.',
 page:{story:{title:'City Cousin, Country Cousin',text:'Ella lives in a *tall apartment* in *Toronto*. From her window she sees thousands of buildings, buses and people: an *urban* area. Her cousin Owen lives on a farm near *Kenora* in the north: a *rural* area. His closest neighbour is *five kilometres* away! When Ella visited, she saw more stars than she had ever seen. When Owen visited Toronto, he rode the *subway*. "Most Ontarians live in the *south*," Ella explained, "near jobs, good farmland and the lakes."',pics:['skyscraper','bus','farm','pine'],
   acts:[[null,'city',['skyscraper','bus','girl'],'So many people!'],['rural','shield',['house','moose','boy'],'So much space!'],['stars','night',['girl','boy'],'Look at all the stars!']]},
  boxes:[{title:'Urban, suburban, rural',ex:[['skyscraper','*urban*: cities, many people close together'],['house','*suburban*: neighbourhoods at the edge of a city'],['barn','*rural*: farms and small towns, lots of space']],cols:3},
   {title:'Population patterns',text:'*Population* means how many people live in a place. Ontario’s south is *dense* (crowded). The north is *sparse* (few people). People settle near *jobs*, *water*, *farmland* and *transportation*.'}],
  cards:[{q:'A farm area with few people is…',pics:['barn'],a:'*rural*'},{q:'Why do most Ontarians live in the south?',a:'*jobs*, farmland, lakes, warmer weather'}],
  words:[['population','the number of people living in a place'],['rural','in the country, away from big cities']]},
 steps:[
  {say:'Read the story',speech:'Ella lives in a tall apartment in Toronto, an urban area. Owen lives on a farm near Kenora, a rural area, where his closest neighbour is five kilometres away. Most Ontarians live in the south.',set:S.row(['skyscraper','bus','farm','pine'])},
  {say:'Urban',speech:'In urban areas, many people live close together in apartments and houses. There are subways, buses, offices and lots of jobs.',set:S.row(['skyscraper','bus','train'],{labels:['apartments','buses','subway']}),
   cues:[['apartments','skyscraper','urban'],['buses','bus','transit'],['subways','train','subway']]},
  {say:'Suburban and rural',speech:'Suburbs have neighbourhoods of houses with yards near a city. Rural areas have farms, forests and small towns, with lots of space between neighbours.',set:S.row(['house','barn','tractor'],{labels:['suburban','rural','farmland']}),
   cues:[['Suburbs','house','suburban'],['Rural areas','barn','rural'],['farms','tractor','space']]},
  {say:'Why the south?',speech:'The south has warmer weather, rich farmland, the Great Lakes, highways and many jobs. The north has long winters, rock and forests, and fewer jobs.',set:S.row(['sun','corn','lake','snowflake'],{labels:['warm','farmland','lakes','long winters']}),
   cues:[['warmer weather','sun','south'],['rich farmland','corn','south'],['the Great Lakes','lake','water'],['long winters','snowflake','north']]}],
 more:{title:'Did you know?',text:'About *9 out of 10* people in Ontario live in the southern part of the province, which is a much smaller area than the north!',pics:['map','city']},
 rounds:[R.q('Where does Ella live?',['an urban area in Toronto','a farm','the north'],'an urban area in Toronto'),R.q('How far was Owen’s closest neighbour?',['five kilometres','next door','100 km'],'five kilometres'),
  R.q('What does *rural* mean?',['in the country','in a big city','underwater'],'in the country'),R.q('Why do most Ontarians live in the south?',['jobs, farmland and lakes','because of polar bears','it is colder'],'jobs, farmland and lakes'),
  R.sort('Sort: *urban* or *rural*?',['urban','rural'],[['skyscraper',0],['barn',1],['bus',0],['tractor',1]]),R.q('What did Ella see in the country?',['more stars','more buildings','a subway'],'more stars'),
  R.tf('Ontario’s north has a sparse population.',true),R.q('What is *population*?',['the number of people in a place','the size of a lake','a kind of map'],'the number of people in a place')],
 tries:[['Make a T-chart: city life vs. country life.','list good things about *both*'],['Where would you like to live? Why?','urban, suburban or rural']]});

/* 23 ─ Land use and the environment */
U({id:'r23',title:'Land use and the environment',strand:'Living in Ontario',codes:['B2.1','B2.2','B2.5','B1.1'],
 guide:{goal:'Investigate short- and long-term effects of land and resource use (cities, farms, mines, forestry, roads) on the environment, and actions that reduce harm.',words:'environment, pollution, habitat, urban sprawl, conservation, effect',ask:['How can a new subdivision affect wetlands?','What happens when fertilizer washes into a lake?','What can communities do to reduce harm?'],home:'Find one way your family can reduce its effect on the land: walk more, compost, save water.'},
 watch:['Every use has an effect!','Paving a wetland for houses means frogs lose their homes. Planting a park brings some of nature back.'],
 fig:'A town growing beside a wetland, with a protected area.',
 page:{story:{title:'Save Frog Marsh!',text:'A company wanted to build *300 new houses* on *Frog Marsh*, a wetland at the edge of town. At the town meeting, Ava spoke up. "Frog Marsh is home to *frogs*, *turtles*, *herons* and ducks. It soaks up rainwater and stops *floods*." A builder said, "But people need *homes*." The council studied the plan. They decided to build the houses on an old empty *parking lot* instead, and to *protect* the marsh. Ava’s class planted *500* native plants along its edge.',pics:['frog','turtle','house','girl'],
   acts:[[null,'pond',['frog','turtle','heron'],'Frog Marsh!'],['town meeting','town',['girl','man','woman'],'Please protect the marsh!'],['planted','pond',['seedling','girl','frog'],'We saved it!']]},
  boxes:[{title:'Effects of land use',ex:[['house','*building*: loses fields, forests, wetlands'],['tractor','*farming*: fertilizer can wash into lakes'],['ore','*mining*: can pollute water'],['logging truck','*logging*: animals lose homes'],['road','*roads*: cut through habitats']],cols:2},
   {title:'Reducing harm',text:'Communities can *protect* wetlands and forests, build on land already used, plant trees, build wildlife crossings, keep farm soil from washing away, and *reduce, reuse, recycle*.'}],
  cards:[{q:'Why are wetlands important?',pics:['frog'],a:'homes for animals; they stop *floods*'},{q:'Name a way to reduce harm.',a:'*protect* nature, plant trees, recycle'}],
  words:[['wetland','land covered by shallow water, like a marsh or swamp'],['conservation','protecting nature and using resources carefully']]},
 steps:[
  {say:'Read the story',speech:'A company wanted to build houses on Frog Marsh. Ava explained that the marsh is home to frogs, turtles and herons, and that it stops floods. The council built the houses on an old parking lot instead and protected the marsh.',set:S.row(['frog','turtle','house','girl'])},
  {say:'Why wetlands matter',speech:'Wetlands are homes for frogs, turtles, herons and ducks. They soak up rain like a sponge, clean the water and stop floods.',set:S.row(['frog','turtle','heron','duck'],{labels:['frogs','turtles','herons','ducks']}),
   cues:[['frogs','frog','home'],['turtles','turtle','home'],['herons','heron','home'],['ducks','duck','home']]},
  {say:'Effects of land use',speech:'New houses can replace fields and forests. Fertilizer from farms can wash into lakes. Mines and roads can harm water and animal habitats.',set:S.row(['house','tractor','road'],{labels:['building','farming','roads']}),
   cues:[['New houses','house','sprawl'],['Fertilizer','tractor','runoff'],['roads','road','habitats cut']]},
  {say:'Smart choices',speech:'Towns can build on land already used, protect wetlands, plant native trees and flowers, and build wildlife crossings.',set:S.row(['seedling','frog','deer'],{labels:['plant','protect','crossings']}),
   cues:[['plant native','seedling','plant'],['protect wetlands','frog','protect'],['wildlife crossings','deer','safe paths']]}],
 more:{title:'Did you know?',text:'Southern Ontario has lost about *70%* of its wetlands since settlers arrived. That is why protecting the ones that are left is so important!',pics:['frog','duck']},
 rounds:[R.q('What did the company want to build?',['300 new houses','a zoo','a school'],'300 new houses'),R.q('Why are wetlands important?',['homes for animals and they stop floods','they make noise','they are dry'],'homes for animals and they stop floods'),
  R.q('Where did the council decide to build?',['on an old parking lot','on the marsh','in the lake'],'on an old parking lot'),R.q('What can wash from farms into lakes?',['fertilizer','sand toys','snow'],'fertilizer'),
  R.pick('Tap the actions that help the environment.',['seedling','recycle','garbage','frog'],['seedling','recycle','frog']),R.q('How many plants did Ava’s class plant?',['500','5','5000'],'500'),
  R.tf('Building on land already used can protect nature.',true),R.q('What is *conservation*?',['protecting nature','building malls','cutting forests'],'protecting nature')],
 tries:[['Find a wetland, park or forest near you. Why is it important?','homes for animals, clean water'],['Write a speech to protect a place you love.','start with *why* it matters']]});

/* 24 ─ Making maps */
U({id:'r24',title:'Making maps of Ontario',strand:'Living in Ontario',codes:['B3.7','B2.3','B3.2'],
 guide:{goal:'Construct print and digital maps that show land use, landform regions or municipalities, using a title, legend, compass rose, scale and grid, and use thematic maps to answer questions.',words:'thematic map, symbol, legend, scale, grid, compass rose, cardinal directions',ask:['What is a thematic map?','Why does a map need a legend?','How do you use a scale?'],home:'Draw a map from your home to your school. Add a legend and a compass rose.'},
 watch:['You are the mapmaker!','A thematic map shows one theme, like land use. Colours and symbols in the legend tell the story.'],
 fig:'A hand-drawn thematic map with a legend.',
 page:{story:{title:'Mapmakers of Room 9',text:'Room 9 made a *thematic map* of their town for the library. Lucas drew the *roads* in grey and the *river* in blue. Amina coloured *farms* green and *houses* yellow. Kenji made *symbols*: a tiny tree for parks, a book for the library, a cross for the hospital. Hana added a *compass rose* and a *scale*: 1 cm = 1 km. Then they drew a *grid* with letters and numbers. "Find the library!" said the librarian. "It’s in *B3*!" everyone shouted.',pics:['map','pencil','compass','library'],
   acts:[[null,'classroom',['map','pencil','boy'],'Let’s make a map!'],['compass rose','classroom',['compass','girl'],'North is up!'],['library','city',['library','book'],'B3!']]},
  boxes:[{title:'A good map has…',ex:[['map','a *title*'],['star','a *legend* with symbols'],['compass','a *compass rose*'],['ruler','a *scale*'],['pencil','a *grid*']],cols:5},
   {title:'Thematic maps',text:'A *thematic map* shows one topic: *land use*, *landform regions*, *population* or *rainfall*. *Digital maps* on a computer can zoom in and out.'}],
  cards:[{q:'What shows directions on a map?',pics:['compass'],a:'the *compass rose*'},{q:'A map about land use is a…',a:'*thematic* map'}],
  words:[['thematic map','a map that shows one topic or theme'],['symbol','a small picture that stands for something on a map']]},
 steps:[
  {say:'Read the story',speech:'Room nine made a thematic map. Roads were grey, the river blue, farms green and houses yellow. Symbols showed parks, the library and the hospital. A compass rose, a scale and a grid helped people find the library in B3.',set:S.row(['map','pencil','compass','library'])},
  {say:'Symbols and legends',speech:'Mapmakers use symbols and colours. The legend explains them: a tree for a park, a book for the library, blue for water.',set:S.row(['tree','book','droplet'],{labels:['park','library','water']}),
   cues:[['a tree for a park','tree','park'],['a book for the library','book','library'],['blue for water','droplet','water']]},
  {say:'Use a grid',speech:'A grid divides the map into squares. Find the row letter, then the column number. The library is in B3.',set:{grid:{rows:3,cols:4,items:{A1:'house',A4:'tree',B3:'library',C2:'hospital',C4:'school'}},cell:'B3'},
   cues:[['B3','B3','library']]},
  {say:'Scale and direction',speech:'The scale shows real distance: one centimetre equals one kilometre. The compass rose shows north, south, east and west.',set:S.row(['ruler','compass','car'],{labels:['1 cm = 1 km','N E S W','travel']}),
   cues:[['The scale','ruler','distance'],['compass rose','compass','directions']]}],
 more:{title:'Did you know?',text:'Long ago, First Nations guides drew maps on *birch bark* and in the sand to show explorers rivers and portages. Many early maps of Canada were made with their help!',pics:['map','canoe']},
 rounds:[R.grid('Tap the square with the *hospital*.',{rows:3,cols:4,items:{A1:'house',A4:'tree',B3:'library',C2:'hospital',C4:'school'}},'C2'),R.grid('Tap square *A4*.',{rows:3,cols:4,items:{A1:'house',A4:'tree',B3:'library',C2:'hospital',C4:'school'}},'A4'),
  R.q('What is a *thematic map*?',['a map about one topic','a treasure map','a globe'],'a map about one topic'),R.q('What does the legend explain?',['the symbols and colours','the weather','the title'],'the symbols and colours'),
  R.q('Scale: 1 cm = 1 km. The park is 4 cm away. How far really?',['4 km','1 km','40 km'],'4 km'),R.q('What colour was the river?',['blue','green','yellow'],'blue'),
  R.tf('A compass rose shows directions.',true),R.q('Where was the library?',['B3','A1','C4'],'B3')],
 tries:[['Make a land-use map of your neighbourhood.','use colours and a *legend*'],['Use a digital map to find your school. Zoom in and out!','ask an adult to help']]});
})();
